SELECT d.d_year, hd.hd_buy_potential, SUM(sr.sr_return_amt) AS total_return_amount, AVG(sr.sr_return_quantity) AS avg_return_quantity FROM store_returns sr JOIN date_dim d ON sr.sr_returned_date_sk = d.d_date_sk JOIN household_demographics hd ON sr.sr_hdemo_sk = hd.hd_demo_sk WHERE d.d_year = 1909 AND hd.hd_income_band_sk = 15 GROUP BY d.d_year, hd.hd_buy_potential HAVING SUM(sr.sr_return_amt) > 359.24
